+import { LanguageStatus as LanguageStatusIcon } from '@/components/language-status';
+import type { AiToolAdminListItem } from '@/data/ai-tool';
+
+interface AiToolLanguageStatusProps {
+  tool: AiToolAdminListItem;
+}
+
+/**
+ * 語言狀態顯示組件
+ * 顯示 AI 工具在不同語言下的翻譯狀態
+ */
+export function AiToolLanguageStatus({ tool }: AiToolLanguageStatusProps) {
+  const languages = ['EN_US', 'ZH_TW', 'JA_JP'] as const;
+
+  return (
+    <div className="flex flex-col gap-1">
+      {languages.map((lang) => {
+        const hasTranslation = tool.translations.some(
+          (t) => t.language === lang && Boolean(t.name?.trim())
+        );
+        const isDefault = tool.defaultLanguage === lang;
+
+        return (
+          <div key={lang} className="flex items-center gap-2 text-xs">
+            <LanguageStatusIcon
+              isDefault={isDefault}
+              hasContent={hasTranslation}
+              size="sm"
+            />
+            <span className="text-muted-foreground">{lang.split('_')[1]}</span>
+          </div>
+        );
+      })}
+    </div>
+  );
+}
