+'use client';
+
+import { ExecutorType } from '@prisma/client';
+import { MessageCircle, Server, Sparkles } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { cn } from '@/lib/utils';
+
+export const EXECUTOR_TYPE_CONFIG: Record<
+  ExecutorType,
+  {
+    Icon: typeof Server;
+    labelKey: 'comfyui' | 'gemini' | 'chatgpt';
+    iconClassName: string;
+  }
+> = {
+  COMFYUI: {
+    Icon: Server,
+    labelKey: 'comfyui',
+    iconClassName: 'text-amber-500'
+  },
+  GEMINI: {
+    Icon: Sparkles,
+    labelKey: 'gemini',
+    iconClassName: 'text-blue-500'
+  },
+  CHATGPT: {
+    Icon: MessageCircle,
+    labelKey: 'chatgpt',
+    iconClassName: 'text-emerald-500'
+  }
+};
+
+const BADGE_BASE_CLASS =
+  'inline-flex items-center whitespace-nowrap rounded-full border border-gray-200 bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-gray-700';
+
+interface ExecutorTypeBadgeProps {
+  executorType: ExecutorType;
+  className?: string;
+}
+
+/**
+ * 執行器類型徽章，灰色底色、依類型著色的 icon。
+ * 表格與篩選選單共用，確保樣式一致。
+ */
+export function ExecutorTypeBadge({
+  executorType,
+  className
+}: ExecutorTypeBadgeProps) {
+  const tExecutor = useTranslations('admin.aiTools.executorType');
+  const config = EXECUTOR_TYPE_CONFIG[executorType];
+
+  if (!config) {
+    return (
+      <div className={BADGE_BASE_CLASS}>
+        {executorType}
+      </div>
+    );
+  }
+
+  const { Icon, labelKey, iconClassName } = config;
+
+  return (
+    <div className={cn(BADGE_BASE_CLASS, className)}>
+      <Icon className={cn('w-3 h-3 mr-1', iconClassName)} />
+      <span>{tExecutor(labelKey)}</span>
+    </div>
+  );
+}
