@@ -0,0 +1,121 @@
+'use client';
+
+import { useMemo } from 'react';
+import { useTranslations } from 'next-intl';
+import {
+  BarChart,
+  Bar,
+  XAxis,
+  YAxis,
+  CartesianGrid,
+  Tooltip,
+  ResponsiveContainer,
+  LabelList,
+  Legend
+} from 'recharts';
+
+import type { AiToolStatsDailyCount } from '@/data/ai-tool-stats';
+
+interface AiToolGenerationTrendChartProps {
+  data: AiToolStatsDailyCount[];
+  isLoading?: boolean;
+}
+
+export function AiToolGenerationTrendChart({
+  data,
+  isLoading
+}: AiToolGenerationTrendChartProps) {
+  const t = useTranslations('admin.aiTools.report');
+  const tCommon = useTranslations('common');
+
+  const chartData = useMemo(() => {
+    return data.map((d) => ({
+      ...d,
+      total: d.imageCount + d.videoCount
+    }));
+  }, [data]);
+
+  if (isLoading) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">{tCommon('loading')}</p>
+      </div>
+    );
+  }
+
+  if (!data || data.length === 0) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">
+          {t('noData', { defaultMessage: '所選期間沒有數據' })}
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <ResponsiveContainer width="100%" height={300}>
+      <BarChart
+        data={chartData}
+        margin={{ top: 5, right: 20, left: -25, bottom: 5 }}
+      >
+        <CartesianGrid strokeDasharray="3 3" />
+        <XAxis
+          dataKey="date"
+          tickFormatter={(tick) =>
+            new Date(tick + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              month: 'short',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          dy={5}
+        />
+        <YAxis allowDecimals={false} />
+        <Tooltip
+          labelFormatter={(label) =>
+            new Date(label + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              year: 'numeric',
+              month: 'long',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          formatter={(value: number, name: string) => [
+            value,
+            name === 'imageCount'
+              ? t('imageCountLabel', { defaultMessage: '圖片數' })
+              : name === 'videoCount'
+              ? t('videoCountLabel', { defaultMessage: '影片數' })
+              : t('totalLabel', { defaultMessage: '總計' })
+          ]}
+        />
+        <Legend
+          formatter={(value) =>
+            value === 'imageCount'
+              ? t('imageCountLabel', { defaultMessage: '圖片數' })
+              : value === 'videoCount'
+              ? t('videoCountLabel', { defaultMessage: '影片數' })
+              : t('totalLabel', { defaultMessage: '總計' })
+          }
+        />
+        <Bar dataKey="imageCount" stackId="a" fill="#8884d8" name="imageCount">
+          <LabelList
+            dataKey="imageCount"
+            position="center"
+            formatter={(value: number) => (value > 0 ? value : '')}
+            style={{ fontSize: '11px', fill: '#fff' }}
+          />
+        </Bar>
+        <Bar dataKey="videoCount" stackId="a" fill="#82ca9d" name="videoCount">
+          <LabelList
+            dataKey="videoCount"
+            position="center"
+            formatter={(value: number) => (value > 0 ? value : '')}
+            style={{ fontSize: '11px', fill: '#fff' }}
+          />
+        </Bar>
+      </BarChart>
+    </ResponsiveContainer>
+  );
+}
