+'use client';
+
+import { TrendingDown, TrendingUp } from 'lucide-react';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+
+interface AiToolStatsCardProps {
+  title: string;
+  mainValue: number;
+  percentage: number;
+  rank: number;
+  changeFromPrevious?: number | null;
+}
+
+export function AiToolStatsCard({
+  title,
+  mainValue,
+  percentage,
+  rank,
+  changeFromPrevious
+}: AiToolStatsCardProps) {
+  const hasChange = changeFromPrevious !== undefined && changeFromPrevious !== null;
+  const isPositive = hasChange && changeFromPrevious > 0;
+  const isNegative = hasChange && changeFromPrevious < 0;
+
+  return (
+    <Card className="border shadow-sm hover:shadow-md transition-shadow relative">
+      <div
+        className="absolute top-[-1px] left-[-1px] w-8 h-6 bg-slate-200 z-10 flex items-start justify-start border border-border"
+        style={{ clipPath: 'polygon(0 0, 0 100%, 100% 0)' }}
+      >
+        <span className="text-[10px] font-bold text-muted-foreground leading-none mt-0.5 ml-0.5">
+          {rank}
+        </span>
+      </div>
+      <CardContent className="p-3 flex flex-col items-center text-center">
+        <div className="flex items-center gap-1.5 mb-2">
+          <p className="text-sm font-medium line-clamp-2 break-all">{title}</p>
+          {hasChange && (
+            <div
+              className={cn(
+                'flex items-center gap-0.5 text-xs font-medium',
+                isPositive && 'text-emerald-600 dark:text-emerald-400',
+                isNegative && 'text-red-600 dark:text-red-400',
+                !isPositive && !isNegative && 'text-muted-foreground'
+              )}
+            >
+              {isPositive ? (
+                <TrendingUp className="h-3 w-3" />
+              ) : isNegative ? (
+                <TrendingDown className="h-3 w-3" />
+              ) : null}
+              <span>
+                {changeFromPrevious! > 0 ? '+' : ''}
+                {changeFromPrevious!.toFixed(1)}%
+              </span>
+            </div>
+          )}
+        </div>
+
+        <div className="flex items-center gap-1 justify-center">
+          <p className="text-xl font-bold">{mainValue.toLocaleString()}</p>
+          <p className="text-xs text-muted-foreground">({percentage}%)</p>
+        </div>
+      </CardContent>
+    </Card>
+  );
+}
