+'use client';
+
+import { useState, useMemo } from 'react';
+import { useQuery } from '@tanstack/react-query';
+import { useTranslations } from 'next-intl';
+import type { DateRange } from 'react-day-picker';
+import { BarChart3 } from 'lucide-react';
+
+import { getAiToolStats } from '@/data/ai-tool-stats';
+import { getUserIdByInvitationCodeIdsAction } from '@/actions/admin/invitation-code';
+import { Card, CardContent } from '@/components/ui/card';
+import {
+  type DateRangeType,
+  getDefaultDateRange,
+  getPreviousDateRange,
+  isUsingDefaultRange
+} from '@/utils/stats';
+
+import AdminPageHeader from '../../_components/admin-page-header';
+
+import {
+  AiToolsReportFilters,
+  AiToolSummaryCards,
+  AiToolRankingList,
+  AiToolGenerationTrendChart
+} from './_components';
+
+export function AiToolsReportClient() {
+  const t = useTranslations('admin.aiTools.report');
+  const [dateRangeType, setDateRangeType] = useState<DateRangeType>('7days');
+  const [selectedDateRange, setSelectedDateRange] = useState<
+    DateRange | undefined
+  >(undefined);
+  const [userIds, setUserIds] = useState<string[]>([]);
+  const [invitationCodeIds, setInvitationCodeIds] = useState<string[]>([]);
+
+  const handleDateRangeTypeChange = (type: DateRangeType) => {
+    setDateRangeType(type);
+    setSelectedDateRange(getDefaultDateRange(type));
+  };
+
+  const dateRange = useMemo(() => {
+    if (selectedDateRange?.from || selectedDateRange?.to) {
+      return selectedDateRange;
+    }
+    return getDefaultDateRange(dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const isUsingDefaultRangeValue = useMemo(() => {
+    return isUsingDefaultRange(selectedDateRange, dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const previousDateRange = useMemo(() => {
+    if (!isUsingDefaultRangeValue) {
+      return null;
+    }
+    return getPreviousDateRange(dateRangeType);
+  }, [dateRangeType, isUsingDefaultRangeValue]);
+
+  const { data: resolvedUserIdsFromCodes } = useQuery({
+    queryKey: ['admin', 'user-ids-by-invitation-codes', invitationCodeIds],
+    queryFn: () => getUserIdByInvitationCodeIdsAction(invitationCodeIds),
+    enabled: invitationCodeIds.length > 0
+  });
+
+  const effectiveUserIds = useMemo(() => {
+    const fromCodes = resolvedUserIdsFromCodes ?? [];
+    const hasFromCodes = invitationCodeIds.length > 0 && fromCodes.length > 0;
+    if (userIds.length === 0 && !hasFromCodes) return [];
+    if (userIds.length === 0) return fromCodes;
+    if (!hasFromCodes) return userIds;
+    return [...new Set([...userIds, ...fromCodes])];
+  }, [invitationCodeIds.length, resolvedUserIdsFromCodes, userIds]);
+
+  const {
+    data: stats,
+    isLoading,
+    error
+  } = useQuery({
+    queryKey: ['ai-tool-stats', dateRange?.from?.toISOString(), dateRange?.to?.toISOString(), effectiveUserIds],
+    queryFn: async () => {
+      return await getAiToolStats({
+        startDate: dateRange?.from,
+        endDate: dateRange?.to,
+        userIds: effectiveUserIds.length > 0 ? effectiveUserIds : undefined
+      });
+    },
+    enabled: !!(dateRange?.from || dateRange?.to)
+  });
+
+  const { data: previousStats, isLoading: isPreviousLoading } = useQuery({
+    queryKey: [
+      'ai-tool-stats',
+      'previous',
+      previousDateRange?.from?.toISOString(),
+      previousDateRange?.to?.toISOString(),
+      effectiveUserIds
+    ],
+    queryFn: async () => {
+      if (!previousDateRange?.from || !previousDateRange?.to) {
+        return null;
+      }
+      return await getAiToolStats({
+        startDate: previousDateRange.from,
+        endDate: previousDateRange.to,
+        userIds: effectiveUserIds.length > 0 ? effectiveUserIds : undefined
+      });
