+'use client';
+
+import { useState, useRef, useEffect } from 'react';
+import { useTranslations } from 'next-intl';
+import { FileImage, Users } from 'lucide-react';
+
+import {
+  Dialog,
+  DialogContent,
+  DialogHeader,
+  DialogFooter,
+  DialogTitle
+} from '@/components/ui/dialog';
+import { Card, CardContent } from '@/components/ui/card';
+import { Alert, AlertDescription } from '@/components/ui/alert';
+import { Button } from '@/components/ui/button';
+import { Badge } from '@/components/ui/badge';
+import {
+  Tooltip,
+  TooltipContent,
+  TooltipProvider,
+  TooltipTrigger
+} from '@/components/ui/tooltip';
+
+const MAX_BADGES = 10;
+
+export type DownloadZipSummary = {
+  totalImages: number;
+  participantCount: number;
+  totalUsersInScope: number;
+  overLimit: boolean;
+};
+
+export type FilterItem = {
+  label: string;
+  value?: string;
+  values?: string[];
+};
+
+type DownloadZipDialogProps = {
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+  summary: DownloadZipSummary | null;
+  filterItems: FilterItem[];
+  onConfirm: () => void;
+  isDownloading?: boolean;
+};
+
+function FilterItemRow({
+  label,
+  value,
+  values,
+  remainingLabel
+}: {
+  label: string;
+  value?: string;
+  values?: string[];
+  remainingLabel: string;
+}) {
+  if (value != null) {
+    return (
+      <div className="flex flex-wrap items-baseline gap-1.5">
+        <span className="text-xs font-medium text-muted-foreground shrink-0">
+          {label}
+        </span>
+        <Badge variant="secondary" className="font-normal">
+          {value}
+        </Badge>
+      </div>
+    );
+  }
+  if (values != null && values.length > 0) {
+    const visible = values.slice(0, MAX_BADGES);
+    const rest = values.slice(MAX_BADGES);
+    const restCount = rest.length;
+    return (
+      <div className="flex flex-wrap items-baseline gap-1.5">
+        <span className="text-xs font-medium text-muted-foreground shrink-0 w-full sm:w-auto">
+          {label}
+        </span>
+        <div className="flex flex-wrap gap-1.5">
+          {visible.map((v, i) => (
+            <Badge key={`${v}-${i}`} variant="secondary" className="font-normal">
+              {v}
+            </Badge>
+          ))}
+          {restCount > 0 && (
+            <TooltipProvider delayDuration={200}>
+              <Tooltip>
+                <TooltipTrigger asChild>
+                  <Badge
+                    variant="outline"
+                    className="font-normal cursor-help border-dashed"
+                  >
+                    {remainingLabel}
+                  </Badge>
+                </TooltipTrigger>
+                <TooltipContent
+                  side="bottom"
+                  className="max-w-xs whitespace-pre-wrap break-words text-start"
+                >
+                  {rest.join('\n')}
+                </TooltipContent>
+              </Tooltip>
+            </TooltipProvider>
+          )}
+        </div>
+      </div>
+    );
+  }
+  return (
+    <div className="flex flex-wrap items-baseline gap-1.5">
+      <span className="text-xs font-medium text-muted-foreground shrink-0">
+        {label}
+      </span>
+      <span className="text-sm text-muted-foreground/55">—</span>
+    </div>
+  );
+}
+
+export function DownloadZipDialog({
+  open,
+  onOpenChange,
+  summary,
+  filterItems,
+  onConfirm,
+  isDownloading = false
+}: DownloadZipDialogProps) {
+  const t = useTranslations('admin.images');
+  const [confirmCooldown, setConfirmCooldown] = useState(false);
+  const cooldownTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
+
+  useEffect(() => {
+    return () => {
+      if (cooldownTimerRef.current) clearTimeout(cooldownTimerRef.current);
+    };
+  }, []);
+
+  const canConfirm =
+    summary &&
+    summary.totalImages > 0 &&
+    !summary.overLimit &&
+    !confirmCooldown;
+
+  const handleConfirm = () => {
+    if (!canConfirm) return;
+    setConfirmCooldown(true);
+    onConfirm();
+    if (cooldownTimerRef.current) clearTimeout(cooldownTimerRef.current);
+    cooldownTimerRef.current = setTimeout(() => {
+      setConfirmCooldown(false);
+      cooldownTimerRef.current = null;
+    }, 2000);
+  };
+
+  return (
+    <Dialog open={open} onOpenChange={onOpenChange}>
+      <DialogContent className="max-w-lg">
+        <DialogHeader>
+          <DialogTitle>{t('downloadZipDialog.title')}</DialogTitle>
+        </DialogHeader>
+        <div className="space-y-4">
+          {/* 篩選條件卡片 */}
+          <Card className="border shadow-sm">
+            <CardContent className="p-4 space-y-3">
+              <p className="text-xs font-medium text-muted-foreground">
+                {t('downloadZipDialog.filterSummary')}
+              </p>
+              {filterItems.length === 0 ? (
+                <p className="text-sm text-muted-foreground">—</p>
+              ) : (
+                <div className="space-y-2">
+                  {filterItems.map((item, idx) => {
+                    const restCount = (item.values?.length ?? 0) - MAX_BADGES;
+                    return (
+                      <FilterItemRow
+                        key={`${item.label}-${idx}`}
+                        label={item.label}
+                        value={item.value}
+                        values={item.values}
+                        remainingLabel={
+                          restCount > 0
+                            ? t('downloadZipDialog.remainingValues', {
+                                count: restCount
+                              })
+                            : ''
+                        }
+                      />
+                    );
+                  })}
+                </div>
+              )}
+            </CardContent>
+          </Card>
+
+          {/* 統計卡片：總張數、參與人數（結果中有圖片的用戶數） */}
+          {summary && (
+            <>
+              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
+                <Card className="border shadow-sm">
+                  <CardContent className="p-4">
+                    <div className="flex items-center justify-center mb-1">
+                      <FileImage className="h-4 w-4 text-muted-foreground" />
+                    </div>
+                    <p className="text-xs text-muted-foreground text-center mb-0.5">
+                      {t('downloadZipDialog.totalImages')}
+                    </p>
+                    <p className="text-lg font-bold text-center">
+                      {summary.totalImages.toLocaleString()}
+                    </p>
+                  </CardContent>
+                </Card>
+                <Card className="border shadow-sm">
+                  <CardContent className="p-4">
+                    <div className="flex items-center justify-center mb-1">
+                      <Users className="h-4 w-4 text-muted-foreground" />
+                    </div>
+                    <p className="text-xs text-muted-foreground text-center mb-0.5">
+                      {t('downloadZipDialog.participantCount')}
+                    </p>
+                    <p className="text-lg font-bold text-center">
+                      {summary.participantCount.toLocaleString()}
+                    </p>
+                  </CardContent>
+                </Card>
+              </div>
+              {summary.overLimit && (
+                <Alert variant="destructive">
+                  <AlertDescription>
+                    {t('downloadZipDialog.overLimit')}
+                  </AlertDescription>
+                </Alert>
+              )}
+            </>
+          )}
+        </div>
+        <DialogFooter>
+          <Button
+            type="button"
+            variant="outline"
+            onClick={() => onOpenChange(false)}
+            disabled={isDownloading}
+          >
+            {t('downloadZipDialog.cancel')}
+          </Button>
+          <Button
+            type="button"
+            onClick={handleConfirm}
+            disabled={!canConfirm}
+          >
+            {t('downloadZipDialog.confirm')}
+          </Button>
+        </DialogFooter>
+      </DialogContent>
+    </Dialog>
+  );
+}
